import React from 'react';
import { Form } from 'react-final-form';
import { useTranslation } from '@getvim/translate';
import CalendarPicker from '../formInputs/calendarPicker';
import { TimingSidebar } from '../../molecules';
import { Button } from '../../atoms';
import { TimePreference } from '../../types';

import './index.less';
import es from './translations/es.json';
import messages from './translations/messages';

export interface TimePreferencesSelectorProps {
  onSubmit: (formValues: TimePreference) => void;
}

export default function TimePreferencesSelector({ onSubmit }: TimePreferencesSelectorProps) {
  const intl = useTranslation({ es });

  return (
    <Form<TimePreference>
      className="time-preferences-selector"
      onSubmit={onSubmit}
      render={({ handleSubmit, form, values }) => (
        <form onSubmit={handleSubmit} className="time-preferences-selector__form">
          <CalendarPicker name="date" sideBar={<TimingSidebar name="timeOptions" />} />

          <div className="time-preferences-selector__form__submit">
            <Button
              buttonType="outline"
              bgColor="white"
              disabled={!values.date || !values.timeOptions || values.timeOptions?.length === 0}
              className="text-semibold"
              text={intl.formatMessage(messages.addSelected)}
              onClick={form.submit}
            />
          </div>
        </form>
      )}
    />
  );
}
